# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FIKIH VE İTİKAT ALANINDA ÖNCÜ ÂLİMLER VE ESERLERİ (12.2.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Fıkhi Yorum Öncüleri (Fakihler)</text>\n  <rect x="32" y="80" width="296" height="46" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="42" y="97" font-size="11" font-weight="bold" fill="#1d4ed8">• Ebû Hanîfe (İmam-ı Âzam - Nu\'mân b. Sâbit):</text>\n  <text x="42" y="114" font-size="10.5" fill="#1e3a8a">Hanefî mezhebi öncüsü; akıl ve istihsana önem verdi. Eseri: <tspan font-weight="bold">el-Fıkhu\'l-Ekber</tspan>.</text>\n  <rect x="32" y="132" width="296" height="46" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="42" y="149" font-size="11" font-weight="bold" fill="#1d4ed8">• İmam Şâfiî (Muhammed b. İdrîs):</text>\n  <text x="42" y="166" font-size="10.5" fill="#1e3a8a">Şâfiî mezhebi öncüsü; fıkıh usulünü sistemleştirdi. Eserleri: <tspan font-weight="bold">er-Risâle, el-Ümm</tspan>.</text>\n  <rect x="32" y="184" width="296" height="46" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="42" y="201" font-size="11" font-weight="bold" fill="#1d4ed8">• İmam Ca\'fer es-Sâdık:</text>\n  <text x="42" y="218" font-size="10.5" fill="#1e3a8a">Ehl-i Beyt soyundan büyük âlim; Ca\'ferî fıkhının öncüsü ve Ebû Hanîfe\'nin hocası.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İtikadi (İnanç) Yorum Öncüleri</text>\n  <rect x="372" y="80" width="296" height="72" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="382" y="99" font-size="11" font-weight="bold" fill="#15803d">• İmam Mâtürîdî (Ebû Mansûr el-Mâtürîdî):</text>\n  <text x="382" y="116" font-size="10.5" fill="#14532d">Semerkant\'ta yetişti; Mâtürîdîlik itikadi mezhebinin kurucusu.</text>\n  <text x="382" y="131" font-size="10.5" fill="#14532d">Vahiy ile aklın uyumunu savundu.</text>\n  <text x="382" y="146" font-size="10.5" font-weight="bold" fill="#166534">Eserleri: Kitâbü\'t-Tevhîd, Te\'vîlâtü\'l-Kur\'ân</text>\n  <rect x="372" y="158" width="296" height="72" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="382" y="177" font-size="11" font-weight="bold" fill="#15803d">• İmam Eş\'arî (Ebü\'l-Hasan el-Eş\'arî):</text>\n  <text x="382" y="194" font-size="10.5" fill="#14532d">Basra ve Bağdat\'ta yetişti; Ehl-i Sünnet inancını aklî ve naklî</text>\n  <text x="382" y="209" font-size="10.5" fill="#14532d">delillerle savunan Eş\'arîlik mezhebinin öncüsüdür.</text>\n  <text x="382" y="224" font-size="10.5" font-weight="bold" fill="#166534">Eserleri: Makâlâtü\'l-İslâmiyyîn, el-İbâne</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİSTAN\'DAN ANADOLU\'YA GÖNÜL MİMARLARI (MUTASAVVIFLAR)</text>\n  <rect x="20" y="45" width="155" height="195" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="97" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Hoca Ahmet Yesevî</text>\n  <text x="97" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">(Pîr-i Türkistan)</text>\n  <text x="28" y="106" font-size="10" fill="#78350f">• İlk Türk tarikatı</text>\n  <text x="34" y="120" font-size="10" fill="#78350f"><tspan font-weight="bold">Yesevîlik</tspan> kurucusu</text>\n  <text x="28" y="140" font-size="10" fill="#78350f">• Türkçe <tspan font-weight="bold">Hikmet</tspan>\'leriyle</text>\n  <text x="34" y="154" font-size="10" fill="#78350f">İslam\'ı sevdirdi.</text>\n  <text x="28" y="176" font-size="10" fill="#78350f">• Temel eseri:</text>\n  <text x="97" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Dîvân-ı Hikmet</text>\n  <text x="97" y="222" text-anchor="middle" font-size="9.5" fill="#78350f">Anadolu erenlerinin hocası</text>\n  <rect x="188" y="45" width="155" height="195" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="265" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Mevlânâ Celâleddîn</text>\n  <text x="265" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">(Konya - Mevlevîlik)</text>\n  <text x="196" y="106" font-size="10" fill="#581c87">• İlahi aşk, hoşgörü ve</text>\n  <text x="202" y="120" font-size="10" fill="#581c87">insan sevgisi vurgusu</text>\n  <text x="196" y="140" font-size="10" fill="#581c87">• "Pergel metaforu" ile</text>\n  <text x="202" y="154" font-size="10" fill="#581c87">yerel ve evrensel bağ</text>\n  <text x="196" y="176" font-size="10" fill="#581c87">• Başlıca eserleri:</text>\n  <text x="265" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">Mesnevî, Fîhi Mâ Fîh</text>\n  <text x="265" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">Dîvân-ı Kebîr</text>\n  <rect x="356" y="45" width="155" height="195" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="433" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Hacı Bektâş-ı Velî</text>\n  <text x="433" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">(Sulucakarahöyük)</text>\n  <text x="364" y="106" font-size="10" fill="#14532d">• "Eline, beline, diline</text>\n  <text x="370" y="120" font-size="10" fill="#14532d">sahip ol" ahlak ilkesi</text>\n  <text x="364" y="140" font-size="10" fill="#14532d">• <tspan font-weight="bold">Dört Kapı Kırk Makam</tspan></text>\n  <text x="370" y="154" font-size="10" fill="#14532d">(Şeriat, Tarikat, Marifet,</text>\n  <text x="370" y="168" font-size="10" fill="#14532d">Hakikat) öğretisi</text>\n  <text x="433" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Eseri: Makâlât</text>\n  <text x="433" y="222" text-anchor="middle" font-size="9.5" fill="#14532d">Bektâşîlik düşüncesinin piri</text>\n  <rect x="524" y="45" width="156" height="195" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="602" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">Yunus Emre</text>\n  <text x="602" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">(Tapduk Emre Dergâhı)</text>\n  <text x="532" y="106" font-size="10" fill="#7f1d1d">• "Yaratılanı severiz</text>\n  <text x="538" y="120" font-size="10" fill="#7f1d1d">Yaratandan ötürü"</text>\n  <text x="532" y="140" font-size="10" fill="#7f1d1d">• Durulmuş arı Türkçeyle</text>\n  <text x="538" y="154" font-size="10" fill="#7f1d1d">tevhid ve ahlak şiirleri</text>\n  <text x="532" y="176" font-size="10" fill="#7f1d1d">• Başlıca eserleri:</text>\n  <text x="602" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Risâletü\'n-Nushiyye</text>\n  <text x="602" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Dîvân</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AHİ EVRAN, SARI SALTUK, HACI BAYRAM-I VELÎ VE ORTAK DEĞER BİLİNCİ</text>\n  <rect x="20" y="46" width="210" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Ahi Evran ve Ahilik</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• Kırşehir merkezli esnaf ve</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">sanatkârlar teşkilatı (<tspan font-weight="bold">Ahilik</tspan>).</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• Fütüvvet ahlakı ile meslek</text>\n  <text x="40" y="143" font-size="10.5" fill="#1e3a8a">eğitimini (çırak-kalfa-usta) ve</text>\n  <text x="40" y="158" font-size="10.5" fill="#1e3a8a">helal kazancı birleştirdi.</text>\n  <text x="32" y="179" font-size="10.5" fill="#1e3a8a">• Kadın kolu: <tspan font-weight="bold">Bâcıyân-ı Rûm</tspan></text>\n  <text x="40" y="194" font-size="10.5" fill="#1e3a8a">(Fatma Bacı öncülüğünde).</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">İş ahlakı ve kalite kontrolü</text>\n  <rect x="245" y="46" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Sarı Saltuk &amp; Hacı Bayram</text>\n  <text x="257" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Sarı Saltuk:</tspan> Balkanlar ve</text>\n  <text x="265" y="107" font-size="10.5" fill="#78350f">Rumeli\'nin (Dobruca) İslamlaşmasına</text>\n  <text x="265" y="122" font-size="10.5" fill="#78350f">öncülük eden alperen derviş.</text>\n  <text x="257" y="146" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Hacı Bayram-ı Velî:</tspan> Ankara\'da</text>\n  <text x="265" y="161" font-size="10.5" fill="#78350f"><tspan font-weight="bold">Bayramîlik</tspan> tarikatını kurdu; el</text>\n  <text x="265" y="176" font-size="10.5" fill="#78350f">emeği ve imece kültürünü yaydı.</text>\n  <text x="265" y="194" font-size="10.5" fill="#78350f">Akşemseddin ve Eşrefoğlu Rûmî\'yi</text>\n  <text x="265" y="209" font-size="10.5" fill="#78350f">yetiştirerek fetih ruhunu besledi.</text>\n  <rect x="470" y="46" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Ortak Değerimiz Olarak Birlik</text>\n  <text x="482" y="92" font-size="10.5" fill="#14532d">• Farklı fıkhi (Hanefî, Şâfiî,</text>\n  <text x="490" y="107" font-size="10.5" fill="#14532d">Ca\'ferî) ve itikadi (Mâtürîdî,</text>\n  <text x="490" y="122" font-size="10.5" fill="#14532d">Eş\'arî) yorumlar dinin aslı değil,</text>\n  <text x="490" y="137" font-size="10.5" font-weight="bold" fill="#15803d">kültürel zenginliğimizdir.</text>\n  <text x="482" y="160" font-size="10.5" fill="#14532d">• Tüm bu şahsiyetler Kur\'an,</text>\n  <text x="490" y="175" font-size="10.5" fill="#14532d">Sünnet, Ehl-i Beyt sevgisi ve</text>\n  <text x="490" y="190" font-size="10.5" fill="#14532d">güzel ahlak paydasında milletimizi</text>\n  <text x="490" y="205" font-size="10.5" font-weight="bold" fill="#166534">kenetleyen ortak değerlerimizdir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
